CREATE TEMP TABLE codes_lignes ON COMMIT DROP AS
WITH base AS (
    SELECT id, upper(regexp_replace(array_to_string(numeros, '-'), '[^A-Za-z0-9-]', '', 'g')) AS numero
    FROM src_ligne
)
SELECT id, CASE
    WHEN char_length(numero) BETWEEN 1 AND 17 AND count(*) OVER (PARTITION BY numero) = 1
        THEN 'BM-' || numero
    ELSE 'BM-V-' || left(md5(id), 15)
END AS code
FROM base;
ALTER TABLE codes_lignes ADD UNIQUE (code);

INSERT INTO public.lignes (code, libelle)
SELECT c.code, left(l.libelle, 150)
FROM src_ligne l JOIN codes_lignes c USING (id)
ON CONFLICT (code) DO NOTHING;

INSERT INTO public.arrets (code, nom, position, actif)
SELECT upper(id), left(nom, 150),
       ST_SetSRID(ST_MakePoint(longitude, latitude), 4326), id <> 'bm:623'
FROM src_arret
ON CONFLICT (code) DO NOTHING;

-- Traiter aussi l'ancien import, uniquement si la position estimée est encore présente.
UPDATE public.arrets
SET actif = false, version = version + 1, modifie_le = now()
WHERE code = 'BM:623' AND actif
  AND ST_X(position) = 57.449337 AND ST_Y(position) = -20.241458;

-- Retirer l'ancien nom attribué à ce point non nommé dans OpenStreetMap.
UPDATE public.arrets
SET nom = 'Arrêt OSM 5533332421',
    position = ST_SetSRID(ST_MakePoint(57.4650956, -20.2405470), 4326),
    version = version + 1, modifie_le = now()
WHERE code = 'BM:413' AND nom = 'Camp Levieux (NHDC Complex)'
  AND ST_X(position) = 57.465096 AND ST_Y(position) = -20.240547;


INSERT INTO public.trajets (code, ligne_id, nom, direction, actif)
SELECT 'BM-T-' || left(md5(t.id), 25), l.id, left(s.libelle, 180), left(t.destination_affichee, 180), true
FROM src_trajet t
JOIN src_ligne s ON s.id = t.ligne_id
JOIN codes_lignes c ON c.id = s.id
JOIN public.lignes l ON l.code = c.code
ON CONFLICT (code) DO NOTHING;

INSERT INTO public.trajet_arrets (trajet_id, ordre, arret_id)
SELECT t.id, p.ordre, a.id
FROM src_passage p
JOIN public.trajets t ON t.code = 'BM-T-' || left(md5(p.trajet_id), 25)
JOIN public.arrets a ON a.code = upper(p.arret_id)
ON CONFLICT (trajet_id, ordre) DO NOTHING;

-- Une séquence existante contradictoire provoque un rollback.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM src_trajet s
        JOIN codes_lignes c ON c.id = s.ligne_id
        JOIN public.trajets t ON t.code = 'BM-T-' || left(md5(s.id), 25)
        JOIN public.lignes l ON l.id = t.ligne_id
        WHERE l.code <> c.code
    ) OR EXISTS (
        SELECT 1 FROM public.trajets t
        JOIN src_trajet s ON t.code = 'BM-T-' || left(md5(s.id), 25)
        JOIN public.trajet_arrets p ON p.trajet_id = t.id
        JOIN public.arrets a ON a.id = p.arret_id
        LEFT JOIN src_passage q ON q.trajet_id = s.id AND q.ordre = p.ordre
        WHERE upper(q.arret_id) IS DISTINCT FROM a.code
    ) THEN
        RAISE EXCEPTION 'Conflit entre le réseau importé et les trajets existants';
    END IF;
END
$$;
COMMIT;
